import React from 'react';
import { CompanionCard } from '../components/CompanionCard';
import { Footer } from '../components/Footer';

// ✅ ONLY 2 TUTORS NOW
const companions = [
  {
    id: "omkar_ai",
    name: "Omkar",
    subject: "Artificial Intelligence & Blockchain",
    description: "Expert in AI, Machine Learning, and Blockchain Technology. Explains complex concepts in simple terms.",
    imageUrl: "/tutor-images/omkar.png",
    modelUrl: null, // No 3D avatar for Omkar (male tutor)
    expertise: ["AI", "Machine Learning", "Blockchain", "Smart Contracts"],
    rating: 4.9,
    sessions: 1200
  },
  {
    id: "priya_biology",
    name: "Priya",
    subject: "Biology",
    description: "Passionate biology teacher who makes learning fun with real-world examples and interactive sessions.",
    imageUrl: "/tutor-images/priya.png",
    modelUrl: "female_glb.glb", // ✅ Female 3D avatar for Priya
    expertise: ["Cell Biology", "Genetics", "Ecology", "Human Anatomy"],
    rating: 4.9,
    sessions: 1050
  }
];

export const CompanionsPage = ({ onSelectCompanion }) => {
  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 flex flex-col">
      <div className="flex-1 py-12 px-4">
        <div className="max-w-7xl mx-auto">
          {/* Header */}
          <div className="text-center mb-12">
            <h1 className="text-4xl md:text-5xl font-extrabold text-white mb-4">
              Choose Your <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">AI Tutor</span>
            </h1>
            <p className="text-gray-400 text-lg max-w-2xl mx-auto">
              Select from our expert AI tutors specialized in different subjects. 
              Each tutor is powered by advanced AI to provide personalized learning experiences.
            </p>
          </div>

          {/* Companions Grid - Now shows only 2 tutors */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-4xl mx-auto">
            {companions.map((companion) => (
              <CompanionCard
                key={companion.id}
                companion={companion}
                onSelect={onSelectCompanion}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Footer */}
      <Footer />
    </div>
  );
};
